import React, { createContext, useCallback, useContext, useEffect, useState } from 'react';

type Theme = 'light' | 'dark' | 'midnight' | 'emerald' | 'charcoal' | 'slate' | 'cocoa';
type Language = 'en' | 'am' | 'om' | 'ti';
type CalendarType = 'ethiopian' | 'gregorian';
type TimeSystem = 'device' | 'ethiopian';

interface ThemeColors {
  primary: string;
  secondary: string;
  background: string;
  surface: string;
  card: string;
  text: string;
  textSecondary: string;
  border: string;
  success: string;
  warning: string;
  error: string;
  tint: string;
  tabBar: string;
  header: string;
}

interface UserProfile {
  name: string;
  businessName: string;
  avatarIndex: number;
  avatarUri?: string;
}

interface NotificationSettings {
  stock: boolean;
  expiration: boolean;
  daily: boolean;
  credit: boolean;
  debt: boolean;
  budget: boolean;
  budgetStatus: boolean;
  expense: boolean;
  largeExpense: boolean;
  recurring: boolean;
  weeklySummary: boolean;
  monthlySummary: boolean;
}

