    'tutorial.activity-ledger.steps.activity-ledger.title': 'Activity Ledger',
    'tutorial.activity-ledger.steps.activity-ledger.desc': 'This is your business activity feed — every transaction, adjustment, and event recorded in chronological order.',
    'tutorial.activity-ledger.steps.al-feed.title': 'Activity Feed',
    'tutorial.activity-ledger.steps.al-feed.desc': 'Every action is listed here: sales, expenses, inventory changes, price adjustments, and payments received.',
