    'tutorial.add-order-item.steps.add-order-item.desc': 'Follow these steps to add a product to your purchase order. You can search for existing inventory items or enter custom details.',
    'tutorial.add-order-item.steps.aoi-name.title': 'Item Name',
    'tutorial.add-order-item.steps.aoi-name.desc': 'Enter the name of the product you want to order. If it exists in inventory, it will auto-fill details.',
