    'tutorial.add-order-item.steps.aoi-company.desc': 'Enter the supplier or company name for this item. This is useful for tracking which vendor supplies the product.',
    'tutorial.add-order-item.steps.aoi-quantity.title': 'Order Quantity',
    'tutorial.add-order-item.steps.aoi-quantity.desc': 'Enter the quantity you want to order. This will be added to the order summary and tracked against the supplier.',
