    'tutorial.add-order-item.steps.aoi-commit.desc': 'Tap to add this item to your purchase order. You can add multiple items before submitting the complete order.',
    'tutorial.adjustment-history.title': 'Adjustment History',
    'tutorial.adjustment-history.subtitle': 'Review all price and stock adjustments',
    'tutorial.adjustment-history.steps.adjustment-history.title': 'Adjustment History',
    'tutorial.adjustment-history.steps.adjustment-history.desc': 'View the complete history of all price changes, stock adjustments, and damaged item records.',
    'tutorial.adjustment-history.steps.ah-filter.title': 'Filter Adjustments',
