    'tutorial.adjustment.steps.adjustment.title': 'Adjustments Hub',
    'tutorial.adjustment.steps.adjustment.desc': 'Make corrections to your inventory — price changes, damaged item logging, and stock corrections. All adjustments are recorded in an immutable audit trail.',
    'tutorial.adjustment.steps.adj-types.title': 'Adjustment Types',
    'tutorial.adjustment.steps.adj-types.desc': 'Choose from three types: Price Increase, Price Decrease, or Damaged Items. Each type creates a permanent record for auditing.',
    'tutorial.adjustment.steps.adj-ledger.title': 'Calibration Ledger',
    'tutorial.adjustment.steps.adj-ledger.desc': 'All past adjustments are recorded here. View the audit trail with timestamps, previous and new values, and reasons for each change.',
    'tutorial.adjustment.steps.adj-stats.title': 'Integrity Statistics',
    'tutorial.adjustment.steps.adj-stats.desc': 'Track monthly corrections, capital leakage from damaged items, and stock integrity scores to monitor inventory health.',
